"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";

type DailyLog = {
  weight: string;
  waist: string;
  calories: string;
  protein: string;
  steps: string;
  water: string;
  sleep: string;

  creatine: boolean;
  intermittent_fasting: boolean;
  workout_completed: boolean;

  workout_type: string;
  notes: string;
};

const initialForm: DailyLog = {
  weight: "",
  waist: "",
  calories: "",
  protein: "",
  steps: "",
  water: "",
  sleep: "",

  creatine: false,
  intermittent_fasting: false,
  workout_completed: false,

  workout_type: "",
  notes: "",
};

function getToday() {
  const date = new Date();

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

export default function DailyCheckin() {
  const [form, setForm] = useState<DailyLog>(initialForm);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [message, setMessage] = useState("");

  const today = getToday();

  useEffect(() => {
    loadToday();
  }, []);

  async function loadToday() {
    setLoading(true);

    const { data, error } = await supabase
      .from("daily_logs")
      .select("*")
      .eq("date", today)
      .maybeSingle();

    if (error) {
      console.error(error);

      setMessage("Gagal mengambil data.");

      setLoading(false);
      return;
    }

    if (data) {
      setForm({
        weight: data.weight?.toString() ?? "",
        waist: data.waist?.toString() ?? "",
        calories: data.calories?.toString() ?? "",
        protein: data.protein?.toString() ?? "",
        steps: data.steps?.toString() ?? "",
        water: data.water?.toString() ?? "",
        sleep: data.sleep?.toString() ?? "",

        creatine: data.creatine ?? false,

        intermittent_fasting:
          data.intermediate_fasting ??
          data.intermittent_fasting ??
          false,

        workout_completed:
          data.workout_completed ?? false,

        workout_type:
          data.workout_type ?? "",

        notes:
          data.notes ?? "",
      });
    }

    setLoading(false);
  }

  function updateField(
    field: keyof DailyLog,
    value: string | boolean
  ) {
    setForm((previous) => ({
      ...previous,
      [field]: value,
    }));
  }

  async function saveCheckin() {
    setSaving(true);
    setMessage("");

    const payload = {
      date: today,

      weight:
        form.weight === ""
          ? null
          : Number(form.weight),

      waist:
        form.waist === ""
          ? null
          : Number(form.waist),

      calories:
        form.calories === ""
          ? null
          : Number(form.calories),

      protein:
        form.protein === ""
          ? null
          : Number(form.protein),

      steps:
        form.steps === ""
          ? null
          : Number(form.steps),

      water:
        form.water === ""
          ? null
          : Number(form.water),

      sleep:
        form.sleep === ""
          ? null
          : Number(form.sleep),

      creatine:
        form.creatine,

      intermittent_fasting:
        form.intermittent_fasting,

      workout_completed:
        form.workout_completed,

      workout_type:
        form.workout_type || null,

      notes:
        form.notes || null,

      updated_at:
        new Date().toISOString(),
    };

    const { error } = await supabase
      .from("daily_logs")
      .upsert(payload, {
        onConflict: "date",
      });

    if (error) {
      console.error(error);

      setMessage(
        `Gagal menyimpan: ${error.message}`
      );
    } else {
      setMessage("✓ Check-in berhasil disimpan");
    }

    setSaving(false);
  }

  if (loading) {
    return (
      <div className="rounded-3xl border border-white/10 bg-zinc-900 p-6">
        <p className="text-zinc-400">
          Loading check-in...
        </p>
      </div>
    );
  }

  return (
    <section className="space-y-5">

      <div>
        <p className="text-xs uppercase tracking-[0.25em] text-zinc-500">
          Daily Check-in
        </p>

        <h2 className="mt-1 text-2xl font-semibold">
          Today
        </h2>

        <p className="mt-1 text-sm text-zinc-500">
          {today}
        </p>
      </div>

      <div className="grid grid-cols-2 gap-3">

        <Input
          label="Weight"
          value={form.weight}
          unit="kg"
          onChange={(value) =>
            updateField("weight", value)
          }
        />

        <Input
          label="Waist"
          value={form.waist}
          unit="cm"
          onChange={(value) =>
            updateField("waist", value)
          }
        />

        <Input
          label="Calories"
          value={form.calories}
          unit="kcal"
          onChange={(value) =>
            updateField("calories", value)
          }
        />

        <Input
          label="Protein"
          value={form.protein}
          unit="g"
          onChange={(value) =>
            updateField("protein", value)
          }
        />

        <Input
          label="Steps"
          value={form.steps}
          unit="steps"
          onChange={(value) =>
            updateField("steps", value)
          }
        />

        <Input
          label="Water"
          value={form.water}
          unit="L"
          step="0.1"
          onChange={(value) =>
            updateField("water", value)
          }
        />

        <Input
          label="Sleep"
          value={form.sleep}
          unit="hours"
          step="0.1"
          onChange={(value) =>
            updateField("sleep", value)
          }
        />

      </div>

      <div className="space-y-3">

        <Toggle
          label="Creatine"
          description="3–5 g"
          checked={form.creatine}
          onChange={(value) =>
            updateField("creatine", value)
          }
        />

        <Toggle
          label="Intermittent Fasting"
          description="16:8"
          checked={
            form.intermittent_fasting
          }
          onChange={(value) =>
            updateField(
              "intermittent_fasting",
              value
            )
          }
        />

        <Toggle
          label="Workout"
          description="Completed today"
          checked={
            form.workout_completed
          }
          onChange={(value) =>
            updateField(
              "workout_completed",
              value
            )
          }
        />

      </div>

      {form.workout_completed && (
        <div>
          <label className="mb-2 block text-sm text-zinc-400">
            Workout Type
          </label>

          <select
            value={form.workout_type}
            onChange={(event) =>
              updateField(
                "workout_type",
                event.target.value
              )
            }
            className="
              w-full
              rounded-2xl
              border
              border-white/10
              bg-zinc-900
              px-4
              py-4
              outline-none
            "
          >
            <option value="">
              Select workout
            </option>

            <option value="Upper">
              Upper
            </option>

            <option value="Lower">
              Lower
            </option>

            <option value="Full Body">
              Full Body
            </option>

            <option value="Cardio">
              Cardio
            </option>
          </select>
        </div>
      )}

      <div>
        <label className="mb-2 block text-sm text-zinc-400">
          Notes
        </label>

        <textarea
          value={form.notes}
          onChange={(event) =>
            updateField(
              "notes",
              event.target.value
            )
          }
          placeholder="How did today feel?"
          className="
            min-h-28
            w-full
            resize-none
            rounded-2xl
            border
            border-white/10
            bg-zinc-900
            px-4
            py-4
            outline-none
            focus:border-white/30
          "
        />
      </div>

      <button
        onClick={saveCheckin}
        disabled={saving}
        className="
          w-full
          rounded-2xl
          bg-white
          py-4
          font-semibold
          text-black
          transition
          hover:bg-zinc-200
          disabled:opacity-50
        "
      >
        {saving
          ? "Saving..."
          : "Save Check-in"}
      </button>

      {message && (
        <p className="text-center text-sm text-zinc-400">
          {message}
        </p>
      )}

    </section>
  );
}

type InputProps = {
  label: string;
  value: string;
  unit: string;
  step?: string;

  onChange: (
    value: string
  ) => void;
};

function Input({
  label,
  value,
  unit,
  step = "1",
  onChange,
}: InputProps) {
  return (
    <div className="rounded-2xl border border-white/10 bg-zinc-900 p-4">

      <p className="text-xs text-zinc-500">
        {label}
      </p>

      <div className="mt-2 flex items-end gap-1">

        <input
          type="number"
          step={step}
          value={value}
          onChange={(event) =>
            onChange(event.target.value)
          }
          placeholder="0"
          className="
            min-w-0
            flex-1
            bg-transparent
            text-2xl
            font-semibold
            outline-none
          "
        />

        <span className="pb-1 text-xs text-zinc-500">
          {unit}
        </span>

      </div>

    </div>
  );
}

type ToggleProps = {
  label: string;
  description: string;
  checked: boolean;

  onChange: (
    value: boolean
  ) => void;
};

function Toggle({
  label,
  description,
  checked,
  onChange,
}: ToggleProps) {
  return (
    <button
      type="button"
      onClick={() =>
        onChange(!checked)
      }
      className="
        flex
        w-full
        items-center
        justify-between
        rounded-2xl
        border
        border-white/10
        bg-zinc-900
        p-4
        text-left
      "
    >

      <div>
        <p className="font-medium">
          {label}
        </p>

        <p className="text-xs text-zinc-500">
          {description}
        </p>
      </div>

      <div
        className={`
          flex
          h-7
          w-12
          items-center
          rounded-full
          p-1
          transition
          ${
            checked
              ? "bg-white"
              : "bg-zinc-700"
          }
        `}
      >
        <div
          className={`
            h-5
            w-5
            rounded-full
            transition
            ${
              checked
                ? "translate-x-5 bg-black"
                : "translate-x-0 bg-white"
            }
          `}
        />
      </div>
      return (
        <section className="checkin"></section>

    </button>
  );
}