'use client';
import Link from 'next/link';
import {usePathname} from 'next/navigation';
import {Home, Dumbbell, Plus, TrendingDown, CalendarDays} from 'lucide-react';
const items=[['/','Home',Home],['/workout','Workout',Dumbbell],['/progress','Progress',TrendingDown],['/calendar','Calendar',CalendarDays]] as const;
export default function BottomNav(){const p=usePathname();return <div className="nav">{items.slice(0,2).map(([href,label,Icon])=><Link key={href} href={href} className={p===href?'active':''}><Icon size={19}/><span>{label}</span></Link>)}<Link href="/?checkin=1" className="navplus" aria-label="Quick check-in"><Plus size={24}/></Link>{items.slice(2).map(([href,label,Icon])=><Link key={href} href={href} className={p===href?'active':''}><Icon size={19}/><span>{label}</span></Link>)}</div>}
